	id := uuid.New()
	if _, err := srv.db.Exec(ctx,
		`INSERT INTO documents(id,workspace_id,owner_id,folder_id,title,deleted_at) VALUES($1,$2,$3,$4,$5,`+deleted+`)`,
		id, workspaceID, adminID, folder, title); err != nil {
