// These run against a real PostgreSQL, because what they are checking is a
// transaction across four tables and a constraint the schema enforces — a fake
// would only confirm that the fake agrees with itself. CI starts a container
// and sets MUNI_TEST_DSN; locally:
//
//	docker run -d --name muni-test -e POSTGRES_PASSWORD=muni -e POSTGRES_DB=muni -p 5433:5432 postgres:16-alpine
//	MUNI_TEST_DSN="postgres://postgres:muni@127.0.0.1:5433/muni?sslmode=disable" go test ./internal/httpapi/
//
// Without it they skip.
// serverUnderTest is a muni talking to a real database, with an administrator
// already signed in — what every test here needs before it can start.
type serverUnderTest struct {
	*httptest.Server
	db    *pgxpool.Pool
	admin *http.Client
	// api is the same Server the handlers run on, so a test can call the
	// enforcement code directly and compare it with what an endpoint reports.
	api *Server
}

func newServerUnderTest(t *testing.T) *serverUnderTest {
	t.Helper()
	srv, db, api := liveServer(t)
	return &serverUnderTest{
		Server: srv,
		db:     db,
		api:    api,
		admin:  signIn(t, srv, "admin@muni.local", "provision-check-1234"),
	}
}

func liveServer(t *testing.T) (*httptest.Server, *pgxpool.Pool, *Server) {
	t.Helper()
	dsn := os.Getenv("MUNI_TEST_DSN")
	if dsn == "" {
		// Skipping is right on a laptop with no container running. In CI it
		// would mean the tests quietly stopped running the day somebody
		// removed the service, and nothing would say so.
		if os.Getenv("CI") != "" {
			t.Fatal("MUNI_TEST_DSN is unset in CI — the postgres service is gone, and these tests would have skipped silently")
		}
		t.Skip("set MUNI_TEST_DSN to run the integration tests")
	}
	ctx := context.Background()
	db, err := database.Open(ctx, dsn)
	if err != nil {
		t.Fatal(err)
	}
	if err := database.Migrate(ctx, db); err != nil {
		t.Fatal(err)
	}
	key := make([]byte, 32)
	_, _ = rand.Read(key)
	sealer, err := cryptoutil.NewSealer(key)
	if err != nil {
		t.Fatal(err)
	}
	// Clear only the accounts these tests make. Truncating users cascades
	// into the settings row and the instance comes back with local login off.
	// workspaces.owner_id has no ON DELETE, so the workspaces go first.
	for _, statement := range []string{
		`DELETE FROM documents WHERE owner_id IN (SELECT id FROM users WHERE email LIKE '%@example.com')`,
		`DELETE FROM documents WHERE workspace_id IN (SELECT id FROM workspaces WHERE owner_id IN (SELECT id FROM users WHERE email LIKE '%@example.com'))`,
		`DELETE FROM workspaces WHERE owner_id IN (SELECT id FROM users WHERE email LIKE '%@example.com')`,
		`DELETE FROM api_keys WHERE user_id IN (SELECT id FROM users WHERE email LIKE '%@example.com')`,
		`DELETE FROM sessions WHERE user_id IN (SELECT id FROM users WHERE email LIKE '%@example.com')`,
		`DELETE FROM users WHERE email LIKE '%@example.com'`,
	} {
		if _, err := db.Exec(ctx, statement); err != nil {
			t.Fatal(err)
		}
	}
	if err := database.Bootstrap(ctx, db, "admin@muni.local", "provision-check-1234", sealer); err != nil {
		t.Fatal(err)
	}
	api := New(db, sealer, BuildInfo{Version: "test"}, slog.New(slog.NewTextHandler(io.Discard, nil)))
	srv := httptest.NewServer(api.Handler())
	t.Cleanup(func() { srv.Close(); db.Close() })
	return srv, db, api
}

func signIn(t *testing.T, srv *httptest.Server, identity, password string) *http.Client {
	t.Helper()
	jar, _ := cookiejar.New(nil)
	client := &http.Client{Jar: jar}
	body, _ := json.Marshal(map[string]string{"identity": identity, "password": password})
	resp, err := client.Post(srv.URL+"/api/v1/auth/login", "application/json", bytes.NewReader(body))
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != 200 {
		raw, _ := io.ReadAll(resp.Body)
		t.Fatalf("login as %s = %d: %s", identity, resp.StatusCode, raw)
	}
	return client
}

func postJSON(t *testing.T, client *http.Client, url string, payload any) (int, map[string]any) {
	t.Helper()
	body, _ := json.Marshal(payload)
	resp, err := client.Post(url, "application/json", bytes.NewReader(body))
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	var out struct {
		Data  map[string]any `json:"data"`
		Error map[string]any `json:"error"`
	}
	raw, _ := io.ReadAll(resp.Body)
	_ = json.Unmarshal(raw, &out)
	if out.Data == nil {
		out.Data = map[string]any{}
	}
	if out.Error != nil {
		out.Data["_errorCode"] = out.Error["code"]
	}
	return resp.StatusCode, out.Data
}

